# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BİR HİLAL UĞRUNA: DİNLEME/İZLEME VE METİN ÇÖZÜMLEME</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Dinleme / İzleme Süreci</text>\n  <text x="38" y="98" font-size="11" fill="#334155">• Dinleme Öncesi: Başlık ve</text>\n  <text x="38" y="114" font-size="11" fill="#334155">  görsellerden içerik tahmini.</text>\n  <text x="38" y="138" font-size="11" fill="#334155">• Dinleme Sırası: Anahtar</text>\n  <text x="38" y="154" font-size="11" fill="#334155">  kelimeleri ve önemli bilgileri</text>\n  <text x="38" y="170" font-size="11" fill="#334155">  not alarak çözümleme.</text>\n  <text x="38" y="194" font-size="11" fill="#334155">• Dinleme Sonrası: Tahminleri</text>\n  <text x="38" y="210" font-size="11" fill="#334155">  kontrol etme ve öz yansıtma.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">Millî Mücadele\'de Çocuklar</text>\n  <text x="258" y="98" font-size="11" fill="#334155">• Tema: Vatanseverlik, özgürlük,</text>\n  <text x="258" y="114" font-size="11" fill="#334155">  fedakârlık ve kahramanlık.</text>\n  <text x="258" y="138" font-size="11" fill="#334155">• Cepheye cephane taşıyan,</text>\n  <text x="258" y="154" font-size="11" fill="#334155">  haber ulaştıran ve bağımsızlık</text>\n  <text x="258" y="170" font-size="11" fill="#334155">  mücadelesine katılan çocuklar.</text>\n  <text x="258" y="194" font-size="11" font-weight="bold" fill="#991b1b">• Derin Anlam: Kanıtlardan</text>\n  <text x="258" y="210" font-size="11" fill="#334155">  hareketle üst düzey çıkarım.</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Metin Yapısı ve Sınıflandırma</text>\n  <text x="478" y="98" font-size="11" fill="#334155">• Sınıflandırma (Tasnif): Unsurları</text>\n  <text x="478" y="114" font-size="11" fill="#334155">  belirli ölçütlere göre ayırma.</text>\n  <text x="478" y="138" font-size="11" fill="#334155">• İkna Etme Teknikleri: Kanıt,</text>\n  <text x="478" y="154" font-size="11" fill="#334155">  tanık gösterme, sayısal veri.</text>\n  <text x="478" y="178" font-size="11" fill="#334155">• Medya Değerlendirme: Norm</text>\n  <text x="478" y="194" font-size="11" fill="#334155">  (ölçüt) belirleyip içeriği</text>\n  <text x="478" y="210" font-size="11" fill="#334155">  güvenilirlik açısından inceleme.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİİLLERDE ANLAM KAYMASI (ZAMAN / KİP KAYMASI) TABLOSU</text>\n  <rect x="25" y="48" width="650" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Biçimce Aldığı Kip Eki ≠ Cümlede Kastettiği Zaman/Anlam (Anlatım Bozukluğu Değildir!)</text>\n  <text x="40" y="100" font-size="11" font-weight="bold" fill="#1e40af">1. Şimdiki Zaman (-yor) → Gelecek Zaman (-ecek):</text>\n  <text x="345" y="100" font-size="11" fill="#334155">&quot;Yarın sabah Ankara\'ya gidiyoruz.&quot; (gideceğiz)</text>\n  <text x="40" y="125" font-size="11" font-weight="bold" fill="#1e40af">2. Şimdiki Zaman (-yor) → Geçmiş Zaman (-di/-miş):</text>\n  <text x="345" y="125" font-size="11" fill="#334155">&quot;Atatürk 19 Mayıs 1919\'da Samsun\'a çıkıyor.&quot; (çıktı)</text>\n  <text x="40" y="150" font-size="11" font-weight="bold" fill="#1e40af">3. Şimdiki Zaman (-yor) → Geniş Zaman (-r/-ar):</text>\n  <text x="345" y="150" font-size="11" fill="#334155">&quot;Her akşam düzenli olarak kitap okuyor.&quot; (okur)</text>\n  <text x="40" y="175" font-size="11" font-weight="bold" fill="#166534">4. Geniş Zaman (-r/-ar) → Geçmiş Zaman (-miş):</text>\n  <text x="345" y="175" font-size="11" fill="#334155">&quot;Nasrettin Hoca bir gün pazara gider.&quot; (gitmiş)</text>\n  <text x="40" y="200" font-size="11" font-weight="bold" fill="#166534">5. Geniş Zaman (-r/-ar) → Gelecek Zaman (-ecek):</text>\n  <text x="345" y="200" font-size="11" fill="#334155">&quot;Haftaya seninle sergide buluşuruz.&quot; (buluşacağız)</text>\n  <text x="40" y="224" font-size="11" font-weight="bold" fill="#991b1b">6. Gelecek Zaman (-ecek) → Emir / Gereklilik:</text>\n  <text x="345" y="224" font-size="11" fill="#334155">&quot;O çalışma masası hemen toplanacak!&quot; (toplansın)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TARİHÎ DÖNEM, BELİRLİ GÜN VE TARİHLERİN YAZIMI VE NOKTALAMA</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Büyük Harflerin Kullanımı (TDK)</text>\n  <text x="44" y="100" font-size="11" fill="#334155">• Tarihî olay, çağ ve dönem adları büyük</text>\n  <text x="44" y="116" font-size="11" font-weight="bold" fill="#92400e">  harfle başlar (kesme işaretiyle ayrılır):</text>\n  <text x="54" y="134" font-size="11" fill="#334155">Kurtuluş Savaşı\'nda, Millî Mücadele\'nin,</text>\n  <text x="54" y="150" font-size="11" fill="#334155">İlk Çağ\'da, Cilalı Taş Devri\'nde.</text>\n  <text x="44" y="176" font-size="11" fill="#334155">• Ulusal, resmî ve belirli gün/hafta adları:</text>\n  <text x="54" y="194" font-size="11" font-weight="bold" fill="#92400e">24 Kasım Öğretmenler Günü, 29 Ekim</text>\n  <text x="54" y="210" font-size="11" font-weight="bold" fill="#92400e">Cumhuriyet Bayramı, Atatürk Haftası.</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Söz Sanatları ve Düşünceyi Geliştirme</text>\n  <text x="378" y="100" font-size="11" fill="#334155">• Söz Sanatları:</text>\n  <text x="388" y="118" font-size="11" fill="#334155">- Benzetme (Teşbih): Zayıfı güçlüye benzetme</text>\n  <text x="388" y="134" font-size="11" fill="#334155">- Kişileştirme (Teşhis): İnsani özellik verme</text>\n  <text x="388" y="150" font-size="11" fill="#334155">- Konuşturma (İntak), Abartma (Mübalağa)</text>\n  <text x="378" y="176" font-size="11" fill="#334155">• Düşünceyi Geliştirme Yolları:</text>\n  <text x="388" y="194" font-size="11" fill="#334155">Tanımlama, Karşılaştırma, Örneklendirme,</text>\n  <text x="388" y="210" font-size="11" fill="#334155">Tanık Gösterme, Sayısal Verilerden Yararlanma.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
